<?php require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json; charset=utf-8');$action=$_GET['action']??'list';if($action==='wishlist'){if($_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);echo json_encode(['ok'=>false]);exit;}$id=(int)$_POST['product_id'];$list=$_SESSION['wishlist']??[];$added=!in_array($id,$list,true);$_SESSION['wishlist']=$added?array_values(array_unique([...$list,$id])):array_values(array_diff($list,[$id]));echo json_encode(['ok'=>true,'added'=>$added]);exit;}if($action==='one'){$st=db()->prepare('SELECT * FROM products WHERE id=? AND status="active"');$st->execute([(int)$_GET['id']]);echo json_encode($st->fetch()?:[]);exit;}$q=trim($_GET['q']??'');$st=db()->prepare('SELECT id,name,slug,price,image FROM products WHERE status="active" AND name LIKE ? LIMIT 10');$st->execute(['%'.$q.'%']);echo json_encode($st->fetchAll());
